# ============================================================================
#  ZENITH ORBITRON - GROUND STATION v7.0
#  SINGLE-FILE, FLAT BUILD
# ============================================================================
#  One flat module.  The application code is the original ground-station GUI;
#  the "zenith" communication package is inlined above it as ordinary module
#  level code (no embedded strings, no exec, no sys.modules tricks).
#
#      Run it with:   python zenith_gs_flat.py
#      Requires:      pip install -r requirements.txt
#
#  Layout of this file
#  -------------------
#      section  1..8   the zenith package modules, concatenated
#      section  9      ZCFG / ZPROTO aliases the GUI code expects
#      section 10      the ground-station GUI (original, minimally patched)
#
#  Generated by tools/make_flat.py - edit zenith/*.py and zenith_gs.py, then
#  regenerate.  A companion build, zenith_gs_standalone.py, keeps the package
#  modules separate (embedded as source); both run identically.
# ============================================================================

from __future__ import annotations      # hoisted here from the inlined modules

# ==========================================================================
#  SECTION - zenith/config.py
# ==========================================================================

"""
Static configuration for the Zenith Orbitron ground station.

Everything the GUI, the graphs, the CSV logger and the two simulations need in
order to agree on *what* a telemetry value is, lives here.  The mapping between
the 15 fields of the rocket's LoRa frame and the GUI channels is declared once
(:data:`CHANNELS`) and is reused everywhere else, so no component can drift out
of sync with another.
"""


from dataclasses import dataclass

# ===========================================================================
# IDENTITY / VERSION
# ===========================================================================
TEAM_ID = "INSPACe-Rocketry-032"
VERSION = (
    "Zenith Orbitron Ground Station v7.1 - E22-900T22D / USB / "
    "BMP390L + BNO085 + INA219 + GNSS"
)

# ===========================================================================
# SERIAL LINK
# ===========================================================================
# The PC is connected directly to the E22-900T22D through a USB-UART adapter.
# The E22 UART is configured for 9600 baud, so 9600 is the GUI default.
# 115200 remains available for older receiver-Teensy setups.
BAUD_CHOICES = ["9600", "19200", "38400", "57600", "115200"]
DEFAULT_BAUD = "9600"            # direct E22 UART -> USB adapter
LORA_UART_BAUD = 9600            # E22-900T22D UART default, firmware-side only
EXPECTED_USB_BAUD = 9600         # direct E22 UART -> USB adapter

# Frame sizes.  The CURRENT payload sends 15 fields; the GUI also still accepts
# the 20/22-field "CAN,..." frame of the previous generation.
EXPECTED_FIELDS = 15             # '@' + 15 CSV fields + '\n'  (rocket TX)
LEGACY_EXPECTED_FIELDS = 20
LEGACY_GPS_FIELDS = 22

LINK_LOST_TIMEOUT_S = 5.0        # matches PACKET_TIMEOUT_MS in the receiver
SERIAL_READ_TIMEOUT_S = 0.05
SERIAL_WRITE_TIMEOUT_S = 0.5
MAX_LINE_BYTES = 4096
RX_BUFFER_GUARD_BYTES = 8192     # runaway-noise guard (same idea as the .ino)

# ===========================================================================
# TELEMETRY CHANNEL MODEL
# ===========================================================================
# `frame_field` is the name of the field in the 15-field '@' LoRa frame that
# feeds this channel.  `None` means: the channel exists in the GUI (graph,
# label, CSV column, ... ) but the CURRENT firmware does not transmit it.
# Such channels are rendered as empty / "not transmitted" - never fabricated.
@dataclass(frozen=True)
class Channel:
    key: str            # key used inside the telemetry dict
    name: str           # human readable name (Serial Monitor, CSV header)
    unit: str
    frame_field: str | None
    color: str


CHANNELS: tuple[Channel, ...] = (
    # -- time ------------------------------------------------------------
    Channel("time_ms",   "Timestamp",            "ms",  "TIMESTAMP_MS",   "#FFFFFF"),
    # -- barometer (BMP390L - the only barometer in the @ frame) ----------
    Channel("bmp_alt",   "BMP390L altitude",     "m",   "ALTITUDE_M",     "#00FFCC"),
    Channel("bmp_temp",  "BMP390L temperature",  "C",   "TEMP_C",         "#00FFCC"),
    Channel("bmp_press", "BMP390L pressure",     "hPa", "PRESSURE_HPA",   "#00FFCC"),
    # -- second barometer (DPS310) - present in the old 20-field CAN frame --
    Channel("dps_alt",   "DPS310 altitude",      "m",   None,             "#FF8A00"),
    Channel("dps_temp",  "DPS310 temperature",   "C",   None,             "#FF8A00"),
    Channel("dps_press", "DPS310 pressure",      "hPa", None,             "#FF8A00"),
    # -- BNO085 ------------------------------------------------------------
    Channel("ax",        "Accel X",              "m/s2", "ACCELEROMETER_DATA", "#FF5252"),
    Channel("ay",        "Accel Y",              "m/s2", "ACCELEROMETER_DATA", "#69F0AE"),
    Channel("az",        "Accel Z",              "m/s2", "ACCELEROMETER_DATA", "#40C4FF"),
    Channel("gx",        "Gyro X",               "deg/s", "GYRO_SPIN_RATE", "#FF5252"),
    Channel("gy",        "Gyro Y",               "deg/s", "GYRO_SPIN_RATE", "#69F0AE"),
    Channel("gz",        "Gyro Z",               "deg/s", "GYRO_SPIN_RATE", "#40C4FF"),
    Channel("roll",      "Roll",                 "deg",  None,             "#FF4081"),
    Channel("pitch",     "Pitch",                "deg",  None,             "#00E5FF"),
    Channel("yaw",       "Yaw",                  "deg",  None,             "#FFD400"),
    # -- INA219 ------------------------------------------------------------
    Channel("vbus",      "INA219 bus voltage",   "V",   "VOLTAGE_V",      "#B388FF"),
    Channel("cur",       "INA219 current",       "mA",  None,             "#FFD400"),
    Channel("pwr",       "INA219 power",         "mW",  None,             "#FFD400"),
)

# Non-numeric / meta values carried alongside the numeric channels.
META_KEYS: tuple[str, ...] = (
    "team_id",
    "packet_count",
    "gnss_time",
    "gnss_latitude",
    "gnss_longitude",
    "gnss_altitude",
    "gnss_sats",
    "flight_state",
)

NUMERIC_KEYS: tuple[str, ...] = tuple(c.key for c in CHANNELS)
FIELD_KEYS: tuple[str, ...] = NUMERIC_KEYS          # legacy alias (CSV writer)
ALL_KEYS: tuple[str, ...] = NUMERIC_KEYS + META_KEYS


def channel(key: str) -> Channel:
    for c in CHANNELS:
        if c.key == key:
            return c
    raise KeyError(key)


def available_keys() -> list[str]:
    return [c.key for c in CHANNELS if c.frame_field is not None]


LEGACY_ONLY_KEYS = {"dps_alt", "dps_temp", "dps_press"}


def missing_channels() -> list[Channel]:
    """Current-firmware channels that are not transmitted.

    The old DPS310 channels remain in the protocol model only for backward
    compatibility with legacy CAN frames; they are not shown as current
    missing telemetry in the GUI.
    """
    return [
        c for c in CHANNELS
        if c.frame_field is None and c.key not in LEGACY_ONLY_KEYS
    ]


def missing_report() -> str:
    return ", ".join(f"{c.name} [{c.unit}]" for c in missing_channels())


