# ==========================================================================
#  SECTION - zenith/protocol.py
# ==========================================================================

"""
Wire protocol for the Zenith Orbitron link.

This module is a faithful Python port of the two Arduino sketches that were
supplied, and it is deliberately free of any Qt / serial dependency so that it
can be unit-tested head-lessly.

--------------------------------------------------------------------------
1. What the ROCKET TRANSMITTER puts on the air (rocket_transmitter.ino)
--------------------------------------------------------------------------
    '@' + <15 comma separated fields> + '\\n'

    #  field              example              notes
    1  TEAM_ID            INSPACe-Rocketry-032
    2  TIMESTAMP_MS       12345                millis() on the rocket
    3  PACKET_COUNT       17                   incremented once per TX
    4  ALTITUDE_M         12.34                barometric, AGL vs pad baseline
    5  PRESSURE_HPA       1013.25
    6  TEMP_C             28.10
    7  VOLTAGE_V          7.940                INA219 bus voltage
    8  GNSS_TIME          12:34:56             UTC hh:mm:ss
    9  GNSS_LATITUDE      13.0827000
   10  GNSS_LONGITUDE     80.2707000
   11  GNSS_ALTITUDE_M    12.30
   12  GNSS_SATS          9
   13  ACCELEROMETER_DATA 0.10;-0.02;9.78      BNO085  (m/s^2)
   14  GYRO_SPIN_RATE     0.10;-0.20;0.00      BNO085  (deg/s)
   15  FLIGHT_STATE       ASCENT

--------------------------------------------------------------------------
2. What the GROUND RECEIVER emits on its USB serial port
--------------------------------------------------------------------------
The stock receiver sketch prints a *human readable report* per packet
(``printTelemetry()``) but never echoes the raw frame.  Both forms are accepted
here, so the GUI works with the firmware exactly as supplied:

  (a) the unmodified receiver's report block::

        ========================================
        VALID ROCKET TELEMETRY
        Team ID: INSPACe-Rocketry-032
        Timestamp: 12345 ms
        ...
        ========================================

  (b) ``RX,<the 15 CSV fields>``  -- one optional line that can be added to the
      receiver sketch (see firmware/ground_receiver) to hand the validated frame
      to the PC byte-for-byte.

  (c) a raw ``@....`` frame -- when a LoRa<->USB dongle is wired straight to the
      PC instead of using the receiver Teensy.

  (d) the legacy ``CAN,time,bmpAlt,bmpT,bmpP,dpsAlt,dpsT,dpsP,ax..gz,roll,pitch,
      yaw,Vbus,mA,mW[,lat,lon]`` frame of the *previous* firmware generation
      (20 or 22 fields), so older payloads keep working.

Every decoded packet is returned as one flat ``dict`` using the channel keys
declared in :mod:`zenith.config`; channels the frame does not contain are set to
``float('nan')` ` (never 0, never invented).  Two derived values are computed
from received data only: ``accel_mag`` (vector norm of ax/ay/az) and
``alt_diff`` (bmp_alt - dps_alt, only when a second barometer exists).
"""


import math
import time
from typing import Any, Iterable








# --------------------------------------------------------------------------
# constants mirrored from the firmware
# --------------------------------------------------------------------------
FRAME_START = "@"
FRAME_END = "\n"
EXPECTED_FIELDS = 15
RECEIVER_TEAM_ID = TEAM_ID

RX_ECHO_PREFIX = "RX,"          # optional receiver-side raw echo
LEGACY_PREFIX = "CAN,"          # previous firmware generation
LEGACY_EXPECTED_FIELDS = 20
LEGACY_GPS_FIELDS = 22

FIELD_NAMES: tuple[str, ...] = (
    "TEAM_ID",
    "TIMESTAMP_MS",
    "PACKET_COUNT",
    "ALTITUDE_M",
    "PRESSURE_HPA",
    "TEMP_C",
    "VOLTAGE_V",
    "GNSS_TIME",
    "GNSS_LATITUDE",
    "GNSS_LONGITUDE",
    "GNSS_ALTITUDE_M",
    "GNSS_SATS",
    "ACCELEROMETER_DATA",
    "GYRO_SPIN_RATE",
    "FLIGHT_STATE",
)

NAN = float("nan")

# Sources of a decoded sample (used for logging / provenance).
SRC_LORA = "lora"          # raw '@' frame straight off the radio
SRC_RX_ECHO = "rx-echo"    # 'RX,' echo from the patched receiver sketch
SRC_REPORT = "rx-report"   # human readable report of the stock receiver
SRC_LEGACY = "legacy-can"  # old 20/22-field CAN frame
SRC_HIL = "hil"            # hardware-in-the-loop self-test (never real data)


# --------------------------------------------------------------------------
# small helpers
# --------------------------------------------------------------------------
def _finite(value: Any) -> bool:
    try:
        return math.isfinite(float(value))
    except (TypeError, ValueError):
        return False


def _to_float(text: str) -> float:
    text = text.strip()
    if not text:
        return NAN
    try:
        return float(text)
    except ValueError:
        return NAN


def split_csv(line: str, max_fields: int | None = None) -> list[str]:
    """Mirror of the receiver's ``splitCSV()`` - semicolons are NOT separators."""
    fields: list[str] = []
    start = 0
    for i in range(len(line) + 1):
        if i == len(line) or line[i] == ",":
            if max_fields is None or len(fields) < max_fields:
                fields.append(line[start:i])
            start = i + 1
    return fields


def parse_triple(text: str) -> tuple[float, float, float] | None:
    """Mirror of the receiver's ``parseTriple()``: 'x;y;z' -> (x, y, z)."""
    first = text.find(";")
    if first < 1:
        return None
    second = text.find(";", first + 1)
    if second <= first + 1 or second >= len(text) - 1:
        return None
    sx, sy, sz = text[:first].strip(), text[first + 1:second].strip(), text[second + 1:].strip()
    if not (sx and sy and sz):
        return None
    try:
        return float(sx), float(sy), float(sz)
    except ValueError:
        return None


def blank_sample() -> dict:
    """A telemetry dict with every channel present and unknown = NaN."""
    sample: dict[str, Any] = {key: NAN for key in NUMERIC_KEYS}
    sample.update(
        {
            "team_id": "",
            "packet_count": 0,
            "gnss_time": "",
            "gnss_latitude": NAN,
            "gnss_longitude": NAN,
            "gnss_altitude": NAN,
            "gnss_sats": 0,
            "flight_state": "",
            # provenance / diagnostics
            "_source": "",
            "_raw": "",
            "_nbytes": 0,
            "_wall": 0.0,
            "_rx_valid": None,
            "_rx_lost": None,
            "_rx_age_ms": None,
        }
    )
    return sample


def _finalise(sample: dict) -> dict:
    """Fill the two derived values that are computed from *received* data."""
    ax, ay, az = sample.get("ax", NAN), sample.get("ay", NAN), sample.get("az", NAN)
    if _finite(ax) and _finite(ay) and _finite(az):
        sample["accel_mag"] = math.sqrt(ax * ax + ay * ay + az * az)
    else:
        sample["accel_mag"] = NAN
    return sample


def _apply_gnss(sample: dict, lat: float, lon: float, alt: float, sats: int,
                gnss_time: str) -> None:
    """Store GNSS only when it is a real fix.

    (0.0, 0.0) is what every GNSS module reports before it has a fix; storing it
    would put the map marker in the Atlantic Ocean, so it is rejected and the
    channel stays NaN -> the map keeps showing 'waiting for fix'.
    """
    sample["gnss_time"] = gnss_time or ""
    if _finite(lat) and _finite(lon) and -90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0:
        if not (abs(lat) < 1e-9 and abs(lon) < 1e-9):
            sample["gnss_latitude"] = lat
            sample["gnss_longitude"] = lon
            # compatibility aliases used by the map tab
            sample["latitude"] = lat
            sample["longitude"] = lon
    if _finite(alt):
        sample["gnss_altitude"] = alt
    try:
        sample["gnss_sats"] = max(0, int(sats))
    except (TypeError, ValueError):
        sample["gnss_sats"] = 0


# --------------------------------------------------------------------------
# (a)/(b)/(c)  15-field frame parsers
# --------------------------------------------------------------------------
def parse_zenith_frame(payload: str, source: str = SRC_LORA,
                       team_id_expected: str | None = RECEIVER_TEAM_ID
                       ) -> dict | None:
    """Parse the 15 CSV fields of a '@' frame (or of a 'RX,' echo).

    Returns ``None`` when the frame is rejected.  All rejection rules are the
    ones implemented in ``parseTelemetry()`` of ground_receiver.ino.
    Pass ``team_id_expected=None`` to accept any team ID (bench testing).
    """
    fields = split_csv(payload.strip())
    if len(fields) != EXPECTED_FIELDS:
        return None

    team_id = fields[0]
    if team_id_expected is not None and team_id != team_id_expected:
        return None

    # timestamp and packet count must be pure decimal digits
    if not (fields[1].isdigit() and fields[2].isdigit()):
        return None

    accel = parse_triple(fields[12])
    if accel is None:
        return None
    gyro = parse_triple(fields[13])
    if gyro is None:
        return None

    state = fields[14].strip()
    if state not in VALID_FLIGHT_STATES:
        return None

    sample = blank_sample()
    sample["_source"] = source
    sample["_raw"] = payload.strip()
    sample["_nbytes"] = len(payload.strip()) + 1
    sample["_wall"] = time.time()

    sample["team_id"] = team_id
    sample["time_ms"] = float(int(fields[1]))
    sample["packet_count"] = int(fields[2])
    sample["bmp_alt"] = _to_float(fields[3])
    sample["bmp_press"] = _to_float(fields[4])
    sample["bmp_temp"] = _to_float(fields[5])
    sample["vbus"] = _to_float(fields[6])
    sample["ax"], sample["ay"], sample["az"] = accel
    sample["gx"], sample["gy"], sample["gz"] = gyro
    sample["flight_state"] = state

    _apply_gnss(
        sample,
        _to_float(fields[8]),
        _to_float(fields[9]),
        _to_float(fields[10]),
        int(_to_float(fields[11])) if _finite(_to_float(fields[11])) else 0,
        fields[7].strip(),
    )
    return _finalise(sample)


# --------------------------------------------------------------------------
# (d)  legacy CAN frame of the previous firmware generation
# --------------------------------------------------------------------------
_LEGACY_NUMERIC = (
    "bmp_alt", "bmp_temp", "bmp_press",
    "dps_alt", "dps_temp", "dps_press",
    "ax", "ay", "az", "gx", "gy", "gz",
    "roll", "pitch", "yaw", "vbus", "cur", "pwr",
)


def parse_legacy_frame(payload: str) -> dict | None:
    """Parse ``CAN,time,<18 values>[,lat,lon]`` (20 or 22 fields)."""
    parts = payload.strip().split(",")
    if len(parts) not in (LEGACY_EXPECTED_FIELDS, LEGACY_GPS_FIELDS):
        return None
    if parts[0] != "CAN":
        return None
    try:
        t_ms = int(parts[1])
        values = [float(p) for p in parts[2:20]]
    except ValueError:
        return None

    sample = blank_sample()
    sample["_source"] = SRC_LEGACY
    sample["_raw"] = payload.strip()
    sample["_nbytes"] = len(payload.strip()) + 1
    sample["_wall"] = time.time()
    sample["team_id"] = RECEIVER_TEAM_ID
    sample["time_ms"] = float(t_ms)
    for key, value in zip(_LEGACY_NUMERIC, values):
        sample[key] = value
    if len(parts) == LEGACY_GPS_FIELDS:
        lat, lon = _to_float(parts[20]), _to_float(parts[21])
        _apply_gnss(sample, lat, lon, NAN, 0, "")
    return _finalise(sample)


# --------------------------------------------------------------------------
# (a)  human readable report block of the stock receiver
# --------------------------------------------------------------------------
_REPORT_KEYS = {
    "Team ID": "team_id",
    "Timestamp": "time_ms",
    "Packet count": "packet_count",
    "Altitude": "bmp_alt",
    "Pressure": "bmp_press",
    "Temperature": "bmp_temp",
    "Voltage": "vbus",
    "GNSS time (UTC)": "gnss_time",
    "GNSS latitude": "gnss_latitude",
    "GNSS longitude": "gnss_longitude",
    "GNSS altitude": "gnss_altitude",
    "GNSS satellites": "gnss_sats",
    "Accelerometer": "accel",
    "Gyroscope": "gyro",
    "Flight state": "flight_state",
    "Valid received": "_rx_valid",
    "Packets lost": "_rx_lost",
    "Last packet age": "_rx_age_ms",
}

# lines the receiver prints that are worth showing in the Serial Monitor
_RECEIVER_NOTES = (
    "Rejected packet",
    "Rejected team ID",
    "WARNING:",
    "ERROR:",
    "SD card",
    "Receiver ready",
    "E22",
)


class ReportBlockParser:
    """Accumulates the receiver's pretty-printed report and turns it into a dict.

    The stock receiver prints the block between two rows of '=' characters::

        ========================================
        VALID ROCKET TELEMETRY
        Team ID: INSPACe-Rocketry-032
        ...
        ========================================
    """

    SEPARATOR = "="

    def __init__(self, team_id: str = RECEIVER_TEAM_ID,
                 strict_team_id: bool = True) -> None:
        self.team_id = team_id
        self.strict_team_id = strict_team_id
        self._buf: list[str] = []

    def reset(self) -> None:
        self._buf.clear()

    def feed(self, line: str) -> dict | None:
        """Consume one USB line; return a sample when a block just completed."""
        stripped = line.strip("\r\n")
        if stripped and set(stripped) == {self.SEPARATOR} and len(stripped) >= 10:
            block, self._buf = self._buf, []
            return self._parse(block)
        self._buf.append(stripped)
        return None

    # -- internals ---------------------------------------------------------
    def _parse(self, block: list[str]) -> dict | None:
        if not any("VALID ROCKET TELEMETRY" in line for line in block):
            return None

        raw: dict[str, str] = {}
        for line in block:
            if ":" not in line:
                continue
            key, _, value = line.partition(":")
            key = key.strip()
            if key in _REPORT_KEYS:
                raw[_REPORT_KEYS[key]] = value.strip()

        if "team_id" not in raw:
            return None
        if self.strict_team_id and raw["team_id"] != self.team_id:
            return None

        sample = blank_sample()
        sample["_source"] = SRC_REPORT
        sample["_raw"] = " | ".join(l for l in block if l)
        sample["_nbytes"] = len(sample["_raw"]) + 1
        sample["_wall"] = time.time()
        sample["team_id"] = raw["team_id"]

        def num(key: str) -> float:
            text = raw.get(key, "")
            for suffix in (" ms", " m", " hPa", " C", " V", " mA", " mW", " deg"):
                if text.endswith(suffix):
                    text = text[: -len(suffix)]
            return _to_float(text)

        sample["time_ms"] = num("time_ms")
        try:
            sample["packet_count"] = int(float(raw.get("packet_count", "0")))
        except ValueError:
            sample["packet_count"] = 0
        sample["bmp_alt"] = num("bmp_alt")
        sample["bmp_press"] = num("bmp_press")
        sample["bmp_temp"] = num("bmp_temp")
        sample["vbus"] = num("vbus")

        accel = parse_triple(raw.get("accel", ""))
        if accel is None:
            return None
        gyro = parse_triple(raw.get("gyro", ""))
        if gyro is None:
            return None
        sample["ax"], sample["ay"], sample["az"] = accel
        sample["gx"], sample["gy"], sample["gz"] = gyro

        state = raw.get("flight_state", "").strip()
        if state not in VALID_FLIGHT_STATES:
            return None
        sample["flight_state"] = state

        _apply_gnss(
            sample,
            num("gnss_latitude"),
            num("gnss_longitude"),
            num("gnss_altitude"),
            int(num("gnss_sats")) if _finite(num("gnss_sats")) else 0,
            raw.get("gnss_time", "").strip(),
        )
        for key in ("_rx_valid", "_rx_lost", "_rx_age_ms"):
            if key in raw:
                try:
                    sample[key] = int(float(raw[key]))
                except ValueError:
                    pass
        return _finalise(sample)


# --------------------------------------------------------------------------
# dispatcher
# --------------------------------------------------------------------------
class LineDispatcher:
    """Turns a stream of USB/serial text lines into validated telemetry dicts.

    ``feed(chunk)`` accepts an arbitrary slice of the serial stream (it may
    contain zero, one or many lines, and may end in the middle of a line).
    It returns ``(samples, messages)`` where *messages* is a list of
    ``(level, text)`` tuples (level in ``{'info', 'warn', 'error'}``) that the
    caller forwards to the Serial Monitor.
    """

    def __init__(self, team_id: str = RECEIVER_TEAM_ID,
                 strict_team_id: bool = True,
                 max_line_bytes: int = MAX_LINE_BYTES) -> None:
        # ``strict_team_id`` mirrors #define RECEIVER_TEAM_ID in the sketch:
        # when False, any team ID is accepted (useful for bench testing with a
        # second payload).  The flight configuration is strict.
        self.team_id = team_id
        self.strict_team_id = strict_team_id
        self.max_line_bytes = max_line_bytes
        self.report = ReportBlockParser(team_id=team_id,
                                        strict_team_id=strict_team_id)
        self._pending = ""            # tail of a line not yet terminated
        self.counts = {
            "lines": 0,
            "frames_ok": 0,
            "frames_rejected": 0,
            "frames_short": 0,
            "notes": 0,
            "dropped": 0,             # lines discarded for being absurdly long
        }

    def reset(self) -> None:
        self.report.reset()
        self._pending = ""
        for key in self.counts:
            self.counts[key] = 0

    # ------------------------------------------------------------------
    def feed(self, chunk: str) -> tuple[list[dict], list[tuple[str, str]]]:
        """Split *chunk* into lines and dispatch each complete one."""
        samples: list[dict] = []
        messages: list[tuple[str, str]] = []
        text = self._pending + (chunk or "")
        if "\n" not in text:
            # no complete line yet - keep buffering (bounded, see below)
            if len(text) > self.max_line_bytes:
                self.counts["dropped"] += 1
                messages.append(
                    ("warn", "[RX] oversized line discarded; resynchronizing"))
                self._pending = ""
            else:
                self._pending = text
            return samples, messages

        parts = text.split("\n")
        self._pending = parts.pop()          # last element is the partial tail
        for line in parts:
            s2, m2 = self._feed_line(line)
            samples.extend(s2)
            messages.extend(m2)
        return samples, messages

    # ------------------------------------------------------------------
    def _feed_line(self, line: str) -> tuple[list[dict], list[tuple[str, str]]]:

    # ------------------------------------------------------------------
        self.counts["lines"] += 1
        samples: list[dict] = []
        messages: list[tuple[str, str]] = []

        text = line.rstrip("\r\n")
        if not text.strip():
            return samples, messages

        # --- (c) raw '@' frame -------------------------------------------
        if text.startswith(FRAME_START):
            sample = parse_zenith_frame(text[1:], SRC_LORA)
            if sample is None:
                self.counts["frames_rejected"] += 1
                messages.append(("error", f"[RX] rejected '@' frame: {text[:120]}"))
            else:
                self.counts["frames_ok"] += 1
                samples.append(sample)
            return samples, messages

        # --- (b) 'RX,' echo from the patched receiver ---------------------
        if text.startswith(RX_ECHO_PREFIX):
            sample = parse_zenith_frame(text[len(RX_ECHO_PREFIX):], SRC_RX_ECHO)
            if sample is None:
                self.counts["frames_rejected"] += 1
                messages.append(("error", f"[RX] rejected echoed frame: {text[:120]}"))
            else:
                self.counts["frames_ok"] += 1
                samples.append(sample)
            return samples, messages

        # --- (d) legacy CAN frame ----------------------------------------
        if text.startswith(LEGACY_PREFIX):
            sample = parse_legacy_frame(text)
            if sample is None:
                self.counts["frames_rejected"] += 1
                messages.append(("error", f"[RX] rejected legacy CAN frame: {text[:120]}"))
            else:
                self.counts["frames_ok"] += 1
                samples.append(sample)
            return samples, messages

        # --- (a) report block of the stock receiver -----------------------
        if set(text.strip()) == {ReportBlockParser.SEPARATOR} and len(text.strip()) >= 10:
            sample = self.report.feed(text)
            if sample is not None:
                self.counts["frames_ok"] += 1
                samples.append(sample)
            return samples, messages

        if self.report._buf or "Team ID:" in text or "VALID ROCKET" in text:
            sample = self.report.feed(text)
            if sample is not None:
                self.counts["frames_ok"] += 1
                samples.append(sample)
            elif any(text.startswith(n) for n in _RECEIVER_NOTES):
                self.counts["notes"] += 1
                messages.append(self._classify(text))
            return samples, messages

        # --- anything else: informational chatter -------------------------
        if any(text.startswith(n) for n in _RECEIVER_NOTES):
            self.counts["notes"] += 1
            messages.append(self._classify(text))
        return samples, messages

    @staticmethod
    def _classify(text: str) -> tuple[str, str]:
        if text.startswith("Rejected") or text.startswith("ERROR"):
            return ("error", f"[RX] {text}")
        if text.startswith("WARNING"):
            return ("warn", f"[RX] {text}")
        return ("info", f"[RX] {text}")


# --------------------------------------------------------------------------
# Serial-Monitor rendering
# --------------------------------------------------------------------------
def _fmt(value: Any, digits: int = 2) -> str:
    """Render a numeric channel, or '--' when it was not transmitted."""
    if not _finite(value):
        return "--"
    return f"{float(value):.{digits}f}"


def format_monitor_line(sample: dict, wall_time: float | None = None) -> str:
    """One readable Serial-Monitor line: names, values and units of what arrived."""
    stamp = time.strftime("%H:%M:%S", time.localtime(wall_time or sample.get("_wall") or time.time()))
    src = sample.get("_source", "")
    parts = [
        f"ALT {_fmt(sample.get('bmp_alt'))} m",
        f"P {_fmt(sample.get('bmp_press'))} hPa",
        f"T {_fmt(sample.get('bmp_temp'))} C",
        f"VBUS {_fmt(sample.get('vbus'), 3)} V",
        "ACC "
        + ";".join(_fmt(sample.get(k)) for k in ("ax", "ay", "az"))
        + " m/s^2",
        "GYR "
        + ";".join(_fmt(sample.get(k)) for k in ("gx", "gy", "gz"))
        + " deg/s",
    ]
    if _finite(sample.get("gnss_latitude")):
        parts.append(
            f"GNSS {sample.get('gnss_time') or '--'} "
            f"{sample['gnss_latitude']:.6f},{sample['gnss_longitude']:.6f} "
            f"{_fmt(sample.get('gnss_altitude'))} m sats {sample.get('gnss_sats', 0)}"
        )
    else:
        parts.append(f"GNSS no fix (sats {sample.get('gnss_sats', 0)})")
    parts.append(f"STATE {sample.get('flight_state') or '--'}")
    return (
        f"[{stamp}] RX#{sample.get('packet_count', 0):05d} "
        f"T+{_fmt(sample.get('time_ms'), 0)} ms ({src}) | " + " | ".join(parts)
    )


def csv_header(extra: Iterable[str] = ()) -> list[str]:
    header = ["Wall_Time", "Source"]
    header += [c.name for c in _channels()]
    header += [
        "Accel_Mag",
        "Alt_Diff",
        "Packet_Count",
        "GNSS_Time",
        "GNSS_Lat",
        "GNSS_Lon",
        "GNSS_Alt_m",
        "GNSS_Sats",
        "Flight_State",
        "Packet_Size_B",
    ]
    header += list(extra)
    return header


def _channels():
      # local import avoids a cycle at import time

    return CHANNELS


def csv_row(sample: dict) -> list:
    

    wall = time.strftime("%H:%M:%S", time.localtime(sample.get("_wall") or time.time()))
    row: list = [wall, sample.get("_source", "")]
    for c in CHANNELS:
        value = sample.get(c.key, NAN)
        row.append("" if not _finite(value) else round(float(value), 6))
    row.append("" if not _finite(sample.get("accel_mag")) else round(sample["accel_mag"], 6))
    row.append(sample.get("packet_count", 0))
    row.append(sample.get("gnss_time", ""))
    for key in ("gnss_latitude", "gnss_longitude", "gnss_altitude"):
        value = sample.get(key, NAN)
        row.append("" if not _finite(value) else round(float(value), 7))
    row.append(sample.get("gnss_sats", 0))
    row.append(sample.get("flight_state", ""))
    row.append(sample.get("_nbytes", 0))
    return row

# ==========================================================================
#  SECTION - zenith/receiver.py
# ==========================================================================

"""Ground-side receiver decoder.

This module is the Python counterpart of
``firmware/ground_receiver/ground_receiver.ino``.

The stock receiver sketch does two things with every packet it gets from the
E22-900T30D radio:

1. it validates the frame (15 CSV fields, team-ID match, numeric sanity,
   valid flight state) - see ``validatePacket()`` in the sketch;
2. it prints a human-readable ``====``-delimited report block.

So the bytes arriving on the USB serial port are **not** the raw ``@`` frame -
they are the pretty report.  ``zenith.protocol.ReportBlockParser`` parses that
block back into a sample dict, which is exactly the same structure that
``parse_zenith_frame()`` produces for a raw frame.  That way the GUI works

* with the receiver sketch exactly as supplied (report block),
* with the optional one-line ``RX,...`` echo patch (see the README),
* with a raw ``@`` frame when the GUI is wired straight to a radio dongle,
* with legacy ``CAN,...`` 20/22-field payloads.

Nothing here invents data: a field that is not present in the received bytes
comes back as NaN and is later rendered as "--".
"""


from typing import Any






class ReceiverDecoder:
    """Streaming decoder: serial bytes/str -> (samples, monitor lines)."""

    def __init__(self, team_id: str = TEAM_ID, strict_team_id: bool = True) -> None:
        self.dispatcher = LineDispatcher(team_id=team_id, strict_team_id=strict_team_id)
        self.decoded = 0
        self.rejected = 0
        self.frames: list[str] = []

    # -----------------------------------------------------------------
    def reset(self) -> None:
        self.dispatcher.reset()
        self.frames.clear()

    def feed(self, payload: str | bytes) -> tuple[list[dict[str, Any]], list[tuple[str, str]]]:
        """Push one read() chunk; return decoded samples + monitor messages."""
        if isinstance(payload, (bytes, bytearray)):
            payload = payload.decode("utf-8", errors="replace")
        samples, messages = self.dispatcher.feed(payload)
        for sample in samples:
            self.frames.append(sample.get("_raw", ""))
            self.decoded += 1
        return samples, messages

    # -----------------------------------------------------------------
    @property
    def raw_queue(self) -> list[str]:
        """Frames seen so far (used by the 'Protocol echo' console filter)."""
        return self.frames

# ==========================================================================
#  SECTION - zenith/telemetry.py
# ==========================================================================

"""Single shared telemetry data model.

Requirement 8 of the task: *"Ensure that the different GUI components do not
maintain conflicting or independent copies of telemetry state."*

Every decoded packet is pushed once into :class:`TelemetryStore` by the GUI
thread.  The graphs, the numeric readouts, the CSV logger, the map tab, the 2D
simulation and the 3D simulation all read from that one store (or receive the
very same dict), so they can never disagree.
"""


import math
import time
from collections import deque
from typing import Any, Iterable




LINK_LOST_TIMEOUT_S = 5.0


class TelemetryStore:
    """Ring-buffer history + latest value for every telemetry channel."""

    def __init__(self, history_len: int = HISTORY_LEN) -> None:
        self.history_len = history_len
        self.t: deque[float] = deque(maxlen=history_len)
        self.history: dict[str, deque[float]] = {
            c.key: deque(maxlen=history_len) for c in CHANNELS
        }
        self.latest: dict[str, Any] = {}
        self.meta: dict[str, Any] = {}

        self.packet_count = 0          # packets accepted since connect
        self.rejected = 0              # packets rejected by the decoder
        self.expected_lost = 0         # gaps reported by the packet-count tracker
        self.first_wall: float | None = None
        self.last_wall: float | None = None
        self.max_alt = NAN
        self.max_accel = NAN
        self.sources: set[str] = set()

    # -----------------------------------------------------------------
    def clear(self) -> None:
        self.t.clear()
        for dq in self.history.values():
            dq.clear()
        self.latest = {}
        self.meta = {}
        self.packet_count = 0
        self.rejected = 0
        self.expected_lost = 0
        self.first_wall = None
        self.last_wall = None
        self.max_alt = NAN
        self.max_accel = NAN
        self.sources.clear()

    # -----------------------------------------------------------------
    def push(self, sample: dict) -> None:
        """Store one validated sample (called from the GUI thread only)."""
        now = sample.get("_wall") or time.time()
        if self.first_wall is None:
            self.first_wall = now
        self.last_wall = now
        self.packet_count += 1
        self.sources.add(sample.get("_source", "?"))

        t_ms = sample.get("time_ms", NAN)
        self.t.append(float(t_ms) / 1000.0 if _finite(t_ms) else NAN)

        for c in CHANNELS:
            value = sample.get(c.key, NAN)
            self.history[c.key].append(float(value) if _finite(value) else NAN)

        self.latest = dict(sample)
        self.meta = {k: sample.get(k) for k in META_KEYS}

        alt = sample.get("bmp_alt", NAN)
        if _finite(alt):
            self.max_alt = alt if not _finite(self.max_alt) else max(self.max_alt, alt)
        mag = sample.get("accel_mag", NAN)
        if _finite(mag):
            self.max_accel = mag if not _finite(self.max_accel) else max(self.max_accel, mag)

    # -----------------------------------------------------------------
    # readers
    # -----------------------------------------------------------------
    def times(self) -> list[float]:
        return list(self.t)

    def series(self, key: str) -> list[float]:
        return list(self.history.get(key, ()))

    def value(self, key: str) -> Any:
        return self.latest.get(key, NAN)

    def finite_series(self, key: str) -> list[float]:
        return [v for v in self.history.get(key, ()) if _finite(v)]

    def has_channel(self, key: str) -> bool:
        """True when at least one finite sample for *key* has been received."""
        return any(_finite(v) for v in self.history.get(key, ()))

    # -----------------------------------------------------------------
    # status
    # -----------------------------------------------------------------
    def link_age(self) -> float | None:
        if self.last_wall is None:
            return None
        return time.time() - self.last_wall

    def link_ok(self) -> bool:
        age = self.link_age()
        return age is not None and age <= LINK_LOST_TIMEOUT_S

    def rate_hz(self) -> float:
        if self.first_wall is None or self.last_wall is None:
            return 0.0
        span = self.last_wall - self.first_wall
        return self.packet_count / span if span > 0.2 else 0.0


# ---------------------------------------------------------------------------
# packet-loss tracking - port of checkPacketLoss() in ground_receiver.ino
# ---------------------------------------------------------------------------
class PacketLossTracker:
    """uint32-rollover-safe gap detector (identical maths to the .ino)."""

    def __init__(self) -> None:
        self.previous: int | None = None
        self.lost = 0
        self.duplicates = 0
        self.out_of_order = 0

    def reset(self) -> None:
        self.previous = None
        self.lost = 0
        self.duplicates = 0
        self.out_of_order = 0

    def update(self, packet_count: int) -> list[tuple[str, str]]:
        """Return a list of ``(level, message)`` warnings produced by this packet."""
        messages: list[tuple[str, str]] = []
        current = int(packet_count) & 0xFFFFFFFF
        if self.previous is None:
            self.previous = current
            return messages

        difference = (current - self.previous) & 0xFFFFFFFF
        if difference == 0:
            self.duplicates += 1
            messages.append(("warn", f"WARNING: duplicate packet count {current}"))
        elif difference < 0x80000000:
            if difference > 1:
                missed = difference - 1
                self.lost += missed
                messages.append(
                    ("warn", f"WARNING: {missed} telemetry packet(s) missing "
                             f"(#{self.previous} -> #{current})")
                )
        else:
            self.out_of_order += 1
            messages.append(("warn", "WARNING: old or out-of-order packet received"))
        self.previous = current
        return messages


# ---------------------------------------------------------------------------
# CSV logging
# ---------------------------------------------------------------------------
class CsvLogger:
    """Append-only CSV writer; missing channels are written as empty cells."""

    def __init__(self, path: str) -> None:
        import csv

        self.path = path
        self._fh = open(path, "w", newline="", encoding="utf-8")
        self._writer = csv.writer(self._fh)
        

        self._writer.writerow(csv_header())

    def write(self, sample: dict) -> None:
        

        self._writer.writerow(csv_row(sample))

    def flush(self) -> None:
        self._fh.flush()

    def close(self) -> None:
        try:
            self._fh.flush()
        except Exception:
            pass
        try:
            self._fh.close()
        except Exception:
            pass


def autoscale_ranges(xs: Iterable[float], series: Iterable[Iterable[float]]):
    """Compute (xmin, xmax, ymin, ymax) ignoring NaN/inf (used by the graphs)."""
    xs = [v for v in xs if _finite(v)]
    ys = [v for group in series for v in group if _finite(v)]
    if not xs:
        return None
    xmin, xmax = min(xs), max(xs)
    if xmax <= xmin:
        xmax = xmin + 1.0
    pad = max((xmax - xmin) * 0.05, 0.5)
    result = [xmin - pad, xmax + pad, None, None]
    if ys:
        lo, hi = min(ys), max(ys)
        if hi - lo < 1.0:
            c = (lo + hi) / 2.0
            lo, hi = c - 1.0, c + 1.0
        else:
            p = (hi - lo) * 0.15
            lo, hi = lo - p, hi + p
        result[2], result[3] = lo, hi
    return tuple(result)

# ==========================================================================
#  SECTION - zenith/attitude.py
# ==========================================================================

"""Attitude maths for the 2D/3D simulations.

IMPORTANT - honesty about what is and is not transmitted
-------------------------------------------------------
The flight software reads a BNO085 quaternion on board but **does not put any
orientation value into the 15-field CSV frame**.  So there is no real
roll/pitch/yaw channel, and the GUI must not invent one.

What this module does instead is *derive* attitude from channels that really
are transmitted:

* **Roll / pitch** - from the accelerometer triple.  While the vehicle is not
  under thrust the accelerometer measures the gravity vector, so
  ``roll  = atan2(ay, az)`` and ``pitch = atan2(-ax, hypot(ay, az))``.
  This is a genuine function of the received data (it is exactly what the
  on-board BNO085 does with its accelerometer), valid whenever
  ``|a| ~= 1 g``; it degrades during boost, which is documented in the GUI
  tooltip and the README.
* **Yaw** - the *rate* gz is transmitted, so yaw is obtained by integrating
  gz over the real packet timestamps.  It drifts; the GUI labels it
  "integrated (drifts)" and it is reset when the rocket is upright on the pad.

Everything else here is plain quaternion/vector maths used to rotate the 3D
rocket mesh with the derived attitude.
"""


import math

import numpy as np

G = 9.80665


# ---------------------------------------------------------------------------
# Tilt from the real accelerometer triple
# ---------------------------------------------------------------------------
def tilt_from_accel(ax: float, ay: float, az: float) -> tuple[float, float, float]:
    """Return ``(roll_deg, pitch_deg, quality)`` from a real accelerometer sample.

    *quality* is 1.0 when the measured specific force is close to 1 g (i.e.
    the gravity estimate is trustworthy) and falls towards 0 as the vehicle
    accelerates.  The simulations use it to fade the tilt out during boost.
    """
    if not all(math.isfinite(v) for v in (ax, ay, az)):
        return (float("nan"), float("nan"), 0.0)
    norm = math.sqrt(ax * ax + ay * ay + az * az)
    if norm < 1e-6:
        return (float("nan"), float("nan"), 0.0)
    # quality: 1 g +- 0.35 g is considered a clean gravity reading
    quality = max(0.0, 1.0 - abs(norm - G) / 0.35)
    quality = 1.0 if quality > 1.0 else quality
    roll = math.degrees(math.atan2(ay, az))
    pitch = math.degrees(math.atan2(-ax, math.hypot(ay, az)))
    return (roll, pitch, quality)


def wrap_deg(angle: float) -> float:
    """Wrap to (-180, 180]."""
    a = math.fmod(angle, 360.0)
    if a > 180.0:
        a -= 360.0
    elif a <= -180.0:
        a += 360.0
    return a


# ---------------------------------------------------------------------------
# Yaw integration from the real gyro spin rate
# ---------------------------------------------------------------------------
class YawIntegrator:
    """Integrates the transmitted gz (deg/s) using the real packet timestamps.

    The flight software sends ``GYRO_SPIN_RATE(x;y;z)``; only the integral over
    time gives an angle, and gyro bias makes that integral drift.  The drift is
    real and is reported - never hidden - and the integrator is re-zeroed
    whenever the vehicle is level and stationary on the pad.
    """

    def __init__(self) -> None:
        self.yaw = 0.0
        self._last_t: float | None = None
        self.drift_warning = False

    def reset(self, yaw: float = 0.0) -> None:
        self.yaw = yaw
        self._last_t = None
        self.drift_warning = False

    def update(self, t_s: float | None, gz: float, level: bool, spin_rate: float) -> float:
        """Advance the estimate; returns yaw in degrees."""
        if t_s is None or not math.isfinite(gz):
            return self.yaw
        if self._last_t is None:
            self._last_t = t_s
            return self.yaw
        dt = t_s - self._last_t
        self._last_t = t_s
        if dt <= 0 or dt > 5.0:          # gap or replay jump: do not integrate
            return self.yaw
        self.yaw = wrap_deg(self.yaw + gz * dt)
        # a level, non-spinning vehicle on the pad means the estimate is pure bias
        if level and abs(spin_rate) < 1.5:
            self.yaw *= 0.9
        self.drift_warning = abs(gz) > 0.5 and dt > 0
        return self.yaw


# ---------------------------------------------------------------------------
# Quaternion helpers (used to orient the 3D rocket mesh)
# ---------------------------------------------------------------------------
def quat_from_euler(roll_deg: float, pitch_deg: float, yaw_deg: float):
    """Body -> world quaternion for intrinsic ZYX (yaw-pitch-roll) rotation."""
    r, p, y = (math.radians(v) / 2.0 for v in (roll_deg, pitch_deg, yaw_deg))
    cr, sr = math.cos(r), math.sin(r)
    cp, sp = math.cos(p), math.sin(p)
    cy, sy = math.cos(y), math.sin(y)
    return np.array([
        cr * cp * cy + sr * sp * sy,
        sr * cp * cy - cr * sp * sy,
        cr * sp * cy + sr * cp * sy,
        cr * cp * sy - sr * sp * cy,
        ], dtype=float)          # (w, x, y, z)


def quat_normalize(q) -> np.ndarray:
    q = np.asarray(q, dtype=float)
    n = float(np.linalg.norm(q))
    return q / n if n > 1e-9 else np.array([1.0, 0.0, 0.0, 0.0])


def quat_slerp(q0, q1, t: float) -> np.ndarray:
    """Shortest-path interpolation - keeps the 3D model from snapping."""
    q0 = quat_normalize(q0)
    q1 = quat_normalize(q1)
    dot = float(np.dot(q0, q1))
    if dot < 0.0:
        q1 = -q1
        dot = -dot
    if dot > 0.9995:
        return quat_normalize(q0 + (q1 - q0) * t)
    theta = math.acos(max(-1.0, min(1.0, dot)))
    sin_t = math.sin(theta)
    a = math.sin((1.0 - t) * theta) / sin_t
    b = math.sin(t * theta) / sin_t
    return quat_normalize(q0 * a + q1 * b)


def quat_to_matrix(q) -> np.ndarray:
    """3x3 rotation matrix for quaternion (w, x, y, z)."""
    q = quat_normalize(q)
    w, x, y, z = q
    return np.array([
        [1 - 2 * (y * y + z * z), 2 * (x * y - w * z), 2 * (x * z + w * y)],
        [2 * (x * y + w * z), 1 - 2 * (x * x + z * z), 2 * (y * z - w * x)],
        [2 * (x * z - w * y), 2 * (y * z + w * x), 1 - 2 * (x * x + y * y)],
        ], dtype=float)


def rotate_vector(q, v) -> np.ndarray:
    return quat_to_matrix(q) @ np.asarray(v, dtype=float)


class AttitudeEstimator:
    """Combines the two derivations above into one smoothed orientation."""

    def __init__(self, smoothing: float = 0.25) -> None:
        self.smoothing = smoothing
        self.roll = 0.0
        self.pitch = 0.0
        self.yaw_integrator = YawIntegrator()
        self.quality = 0.0
        self._init = False

    def reset(self) -> None:
        self.roll = self.pitch = 0.0
        self.quality = 0.0
        self._init = False
        self.yaw_integrator.reset()

    def update(self, sample: dict) -> tuple[float, float, float]:
        """Return ``(roll, pitch, yaw)`` in degrees, derived from real data."""
        ax = _f(sample.get("ax"))
        ay = _f(sample.get("ay"))
        az = _f(sample.get("az"))
        roll, pitch, quality = tilt_from_accel(ax, ay, az)
        t_s = _f(sample.get("time_ms"))
        t_s = None if t_s is None else t_s / 1000.0
        spin = math.hypot(_f(sample.get("gx")) or 0.0, _f(sample.get("gy")) or 0.0)
        self.quality = quality
        if not math.isfinite(roll):
            # no usable accelerometer triple - hold the last known attitude
            return (self.roll, self.pitch, self.yaw_integrator.yaw)

        level = quality > 0.6 and abs(ax) < 2.0 and abs(ay) < 2.0
        yaw = self.yaw_integrator.update(t_s, _f(sample.get("gz")) or 0.0, level, spin)
        if not self._init:
            self.roll, self.pitch = roll, pitch
            self._init = True
        else:
            a = self.smoothing * (0.35 + 0.65 * quality)
            self.roll += (roll - self.roll) * a
            self.pitch += (pitch - self.pitch) * a
        return (self.roll, self.pitch, yaw)

    @property
    def quaternion(self) -> np.ndarray:
        return quat_from_euler(self.roll, self.pitch, self.yaw_integrator.yaw)


def _f(value) -> float:
    try:
        v = float(value)
    except (TypeError, ValueError):
        return float("nan")
    return v

# ==========================================================================
#  SECTION - zenith/transmitter.py
# ==========================================================================

"""Rocket-side payload: the exact frame the .ino transmitter builds.

Why this module exists
----------------------
``firmware/rocket_transmitter/rocket_transmitter.ino`` runs on a Teensy 4.1
that is bolted inside the rocket.  There is no way for a desktop GUI to
"run" that sketch, so this module is a byte-for-byte Python mirror of
``buildSensorString()`` / ``transmitPacket()`` from the sketch:

    '@' + <15 comma-separated fields> + '\\n'

It is used ONLY for:

* the unit tests in ``tests/`` (they build a frame here and check that
  :mod:`zenith.receiver` decodes it back);
* the **Hardware-In-The-Loop self test** (GUI -> ``Tools`` -> ``Run HIL self
  test``) which pushes the frame through the *real* serial port, through the
  *real* receiver sketch, back into the *real* decoder - proving the whole
  chain works without flying a rocket.

It never produces a value that is shown in the GUI.  The GUI only ever
displays data that arrived on the serial port.
"""


import math
import time
from typing import Any




# Transmit period of the flight software (LORA_PERIOD_MS in the .ino).
TRANSMIT_INTERVAL_MS = 1000


def _triple(values, fmt: str = "%.2f") -> str:
    """'x;y;z' with no spaces - byte-identical to String(v, 2) in the sketch."""
    return ";".join(fmt % float(v) for v in values)


def build_frame(
    timestamp_ms: int,
    altitude_m: float,
    pressure_hpa: float,
    temperature_c: float,
    voltage_v: float,
    accel: tuple[float, float, float],
    gyro: tuple[float, float, float],
    gnss: tuple[str, float, float, float, int],
    flight_state: str | int,
    team_id: str = TEAM_ID,
    packet_count: int | None = None,
) -> str:
    """Return one complete wire frame (ending in '\\n').

    The argument order mirrors the 15 fields of the protocol exactly; see
    ``zenith.protocol.FIELD_NAMES``.
    """
    state_name = flight_state
    if isinstance(flight_state, int):
        state_name = FLIGHT_STATE_NAMES.get(flight_state, str(flight_state))
    state_name = str(state_name).strip().upper()

    # NOTE: the order below is the order of buildTelemetryPacket() in
    # rocket_transmitter.ino - accel/gyro come *after* the GNSS block.
    fields = [
        str(team_id),                       #  0 TEAM_ID
        f"{int(timestamp_ms)}",             #  1 TIMESTAMP_MS
        str(int(packet_count if packet_count is not None else 0)),  # 2 PACKET_COUNT
        f"{altitude_m:.2f}",                #  3 ALTITUDE_M
        f"{pressure_hpa:.2f}",              #  4 PRESSURE_HPA
        f"{temperature_c:.2f}",             #  5 TEMP_C
        f"{voltage_v:.3f}",                 #  6 VOLTAGE_V
        str(gnss[0]),                       #  7 GNSS_TIME
        f"{gnss[1]:.6f}",                   #  8 GNSS_LATITUDE
        f"{gnss[2]:.6f}",                   #  9 GNSS_LONGITUDE
        f"{gnss[3]:.2f}",                   # 10 GNSS_ALTITUDE_M
        str(int(gnss[4])),                  # 11 GNSS_SATS
        _triple(accel),       # 12 ACCELEROMETER_DATA
        _triple(gyro),        # 13 GYRO_SPIN_RATE
        state_name,                         # 14 FLIGHT_STATE
    ]
    if len(fields) != len(FIELD_NAMES):
        raise ValueError(f"frame must have {len(FIELD_NAMES)} fields, got {len(fields)}")
    return FRAME_START + ",".join(fields) + FRAME_END


def build_from_sample(sample: dict[str, Any]) -> str:
    """Re-encode a previously decoded sample dict back into a wire frame.

    Used by the replay tooling (``tools/replay.py``) and by the tests.  Any
    field that is NaN - i.e. a channel the payload never transmitted - is
    encoded as ``0.00`` so that the frame stays parseable; the decoder will
    mark it missing again on the other side.
    """
    def num(key: str, default: float = 0.0) -> float:
        v = sample.get(key, default)
        try:
            v = float(v)
        except (TypeError, ValueError):
            return default
        return default if not math.isfinite(v) else v

    return build_frame(
        timestamp_ms=int(num("time_ms")),
        altitude_m=num("bmp_alt"),
        pressure_hpa=num("bmp_press"),
        temperature_c=num("bmp_temp"),
        voltage_v=num("vbus"),
        accel=(num("ax"), num("ay"), num("az")),
        gyro=(num("gx"), num("gy"), num("gz")),
        gnss=(
            str(sample.get("gnss_time", "") or ""),
            num("latitude"),
            num("longitude"),
            num("gnss_altitude"),
            int(num("gnss_sats")),
        ),
        flight_state=str(sample.get("flight_state", "STANDBY") or "STANDBY"),
        packet_count=int(num("packet_count")),
    )


# ---------------------------------------------------------------------------
# Synthetic *reference* trajectory - used only by the HIL self test and by
# ``sample_data/`` generation.  Clearly named so it can never be confused with
# real telemetry: GUI shows "HIL" / "replay" as the source of these packets.
# ---------------------------------------------------------------------------
def reference_trajectory(elapsed_s: float) -> dict[str, Any]:
    """Deterministic stand-in for the sensor suite, for bench testing only."""
    burn = 3.2
    apogee_t = 12.5
    if elapsed_s < burn:
        alt = 0.5 * 95.0 * elapsed_s * elapsed_s
        az = 95.0
        state = "ASCENT"
    elif elapsed_s < apogee_t:
        v0 = 95.0 * burn
        dt = elapsed_s - burn
        alt = 0.5 * v0 * burn + v0 * dt - 0.5 * 9.80665 * dt * dt
        az = -9.80665
        state = "BURNOUT"
    elif elapsed_s < 34.0:
        # parachute descent at ~6 m/s from apogee
        alt = max(0.0, 700.0 - 6.0 * (elapsed_s - apogee_t))
        az = -9.80665 + 3.0 * math.sin(elapsed_s)
        state = "DESCENT"
    else:
        alt = 0.0
        az = -9.80665
        state = "LANDED"

    pressure = 1013.25 * math.exp(-alt / 8434.0)
    temp = 30.0 - 0.0065 * alt
    voltage = max(3.4, 5.05 - 0.0006 * elapsed_s)
    spin = 6.0 if state in ("BOOST", "COAST") else 1.2
    return {
        "time_ms": int(elapsed_s * 1000.0),
        "bmp_alt": round(alt, 2),
        "bmp_press": round(pressure, 2),
        "bmp_temp": round(temp, 2),
        "vbus": round(voltage, 2),
        "ax": round(1.4 * math.sin(elapsed_s * 2.1), 2),
        "ay": round(1.1 * math.cos(elapsed_s * 1.7), 2),
        "az": round(az, 2),
        "gx": round(spin * math.sin(elapsed_s * 0.9), 2),
        "gy": round(spin * math.cos(elapsed_s * 0.9), 2),
        "gz": round(12.0 * math.sin(elapsed_s * 0.3), 2),
        "gnss_time": time.strftime("%H%M%S.00", time.gmtime(elapsed_s)),
        "latitude": round(13.0827 + elapsed_s * 1e-5, 6),
        "longitude": round(80.2707 + elapsed_s * 1e-5, 6),
        "gnss_altitude": round(alt + 6.0, 2),
        "gnss_sats": 9,
        "flight_state": state,
    }


def reference_frames(count: int = 60, dt: float = 1.0) -> list[str]:
    """``count`` frames of bench-test traffic, 1 Hz (matches the flight TX rate)."""
    frames = []
    for i in range(count):
        sample = reference_trajectory(i * dt)
        sample["packet_count"] = i + 1          # mirrors packetCounter in the .ino
        frames.append(build_from_sample(sample))
    return frames

# ==========================================================================
#  SECTION - zenith/serial_link.py
# ==========================================================================

"""Serial worker thread.

Requirement 9: *"Keep the GUI responsive by moving serial I/O to a separate
worker thread and communicating with the main thread using Qt signals/slots.
Do not update GUI widgets or 3D objects from the worker thread."*

``SerialWorker`` is a ``QThread`` that owns the ``pyserial`` port.  It only ever
emits *plain Python data* (str, dict, float) through Qt signals; every widget,
plot and 3D object is touched on the GUI thread, in the slots connected to
those signals.  Nothing in this file imports or touches a widget.
"""


import time

from PyQt6.QtCore import QThread, pyqtSignal

try:  # pragma: no cover - exercised only on a machine without pyserial
    import serial
    from serial import SerialException
    from serial.tools import list_ports
except Exception:  # pragma: no cover
    serial = None  # type: ignore
    list_ports = None  # type: ignore

    class SerialException(Exception):  # type: ignore
        pass


class SerialWorker(QThread):
    """Reads the ground receiver's USB port and emits decoded lines/samples."""

    line_received = pyqtSignal(str)          # raw text, for the Serial Monitor
    sample_decoded = pyqtSignal(dict)        # validated sample dict
    message = pyqtSignal(str, str)           # (level, text) -> monitor notice
    error = pyqtSignal(str)                  # fatal port error
    state_changed = pyqtSignal(str)          # 'connecting' | 'connected' | ...

    def __init__(self, port: str, baud: int, decoder, parent=None) -> None:
        super().__init__(parent)
        self.port = port
        self.baud = baud
        self.decoder = decoder
        self._running = True
        self._port = None

    # -----------------------------------------------------------------
    def stop(self) -> None:
        """Ask the thread to finish; safe to call from the GUI thread."""
        self._running = False
        self.requestInterruption()

    def send(self, text: str) -> None:
        """Write *text* to the port (used by the HIL loop-back self test)."""
        try:
            if self._port and self._port.is_open:
                self._port.write(text.encode("utf-8", errors="replace"))
                self._port.flush()
            else:
                self.message.emit("warn", "TX ignored: port is not open")
        except Exception as exc:  # pragma: no cover - hardware dependent
            self.message.emit("error", f"TX failed: {exc}")

    # -----------------------------------------------------------------
    def run(self) -> None:  # noqa: D102 - QThread entry point
        if serial is None:
            self.error.emit("pyserial is not installed (pip install pyserial)")
            return

        try:
            self._port = serial.Serial(
                port=self.port,
                baudrate=self.baud,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=0.2,
                write_timeout=1.0,
                rtscts=False,
                dsrdtr=False,
            )
        except SerialException as exc:
            self.error.emit(f"could not open {self.port}: {exc}")
            return
        except Exception as exc:  # pragma: no cover
            self.error.emit(f"could not open {self.port}: {exc}")
            return

        self.state_changed.emit("connected")
        self.message.emit("info", f"listening on {self.port} @ {self.baud} baud")

        try:
            try:
                self._port.reset_input_buffer()
            except Exception:
                pass
            while self._running and not self.isInterruptionRequested():
                try:
                    waiting = self._port.in_waiting
                except Exception:
                    waiting = 0
                if waiting:
                    chunk = self._port.read(waiting)
                else:
                    # pyserial 'timeout' already bounds read(); sleep keeps the
                    # loop cheap without busy-spinning.
                    chunk = self._port.read(1)
                if not chunk:
                    continue
                try:
                    samples, messages = self.decoder.feed(chunk)
                except Exception as exc:  # decoder bug must not kill the link
                    self.message.emit("error", f"decoder error: {exc}")
                    continue
                for level, text in messages:
                    self.message.emit(level, text)
                if chunk:
                    self.line_received.emit(
                        chunk.decode("utf-8", errors="replace")
                    )
                for sample in samples:
                    sample["_wall"] = time.time()
                    self.sample_decoded.emit(sample)
        except SerialException as exc:
            self.error.emit(f"serial error: {exc}")
        except Exception as exc:  # pragma: no cover
            self.error.emit(f"unexpected serial error: {exc}")
        finally:
            try:
                if self._port and self._port.is_open:
                    self._port.close()
            except Exception:
                pass
            self.state_changed.emit("disconnected")


# ---------------------------------------------------------------------------
# Replay source - plays a log file through the *same* decoder, so recorded
# flights can be reviewed with the identical code path as a live link.
# ---------------------------------------------------------------------------
class ReplayWorker(QThread):
    """Feeds a saved log/CSV through the decoder at a chosen speed."""

    line_received = pyqtSignal(str)
    sample_decoded = pyqtSignal(dict)
    message = pyqtSignal(str, str)
    finished_replay = pyqtSignal()

    def __init__(self, path: str, decoder, speed: float = 1.0, parent=None) -> None:
        super().__init__(parent)
        self.path = path
        self.decoder = decoder
        self.speed = speed
        self._running = True

    def stop(self) -> None:
        self._running = False
        self.requestInterruption()

    def run(self) -> None:  # noqa: D102
        try:
            with open(self.path, "r", encoding="utf-8", errors="replace") as fh:
                lines = fh.readlines()
        except OSError as exc:
            self.message.emit("error", f"cannot read {self.path}: {exc}")
            return

        self.message.emit("info", f"replaying {self.path} ({len(lines)} lines)")
        for line in lines:
            if not self._running or self.isInterruptionRequested():
                break
            samples, messages = self.decoder.feed(line)
            for level, text in messages:
                self.message.emit(level, text)
            self.line_received.emit(line)
            for sample in samples:
                sample["_wall"] = time.time()
                self.sample_decoded.emit(sample)
            if self.speed > 0:
                self.msleep(int(1000 / max(self.speed, 0.1)))
        self.finished_replay.emit()


def available_ports() -> list[str]:
    """Best-effort list of serial port device paths (never raises)."""
    ports: list[str] = []
    try:
        if list_ports is not None:
            ports = [p.device for p in list_ports.comports()]
    except Exception:
        ports = []
    if not ports:
        import glob

        ports = sorted(glob.glob("/dev/ttyUSB*") + glob.glob("/dev/ttyACM*")
                       + glob.glob("/dev/cu.usb*") + glob.glob("/dev/ttyS*"))
    return ports

